import{_ as e,o as s,c as n,a0 as o}from"./chunks/framework.TJhnt8t4.js";const u=JSON.parse('{"title":"Реализация собственного коннектора","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guide/custom-connector.md","filePath":"ru/guide/custom-connector.md"}'),t={name:"ru/guide/custom-connector.md"};function r(i,a,l,c,p,d){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="реализация-собственного-коннектора" tabindex="-1">Реализация собственного коннектора <a class="header-anchor" href="#реализация-собственного-коннектора" aria-label="Permalink to &quot;Реализация собственного коннектора&quot;">​</a></h1><p>Использование <a href="./android-sdk">Android</a> или <a href="./ios-macos-sdk">iOS/macOS</a> SDK необязательно. Протокол, который они реализуют, публичный и описан здесь — клиент может получить реестр, проверить его и применить пины любым HTTP/TLS-стеком, который уже используется. Это та же спецификация, которой следуют оба официальных SDK; полное криптографическое обоснование — в разделе <a href="./architecture">Архитектура</a>.</p><h2 id="что-должен-делать-ваш-коннектор" tabindex="-1">Что должен делать ваш коннектор <a class="header-anchor" href="#что-должен-делать-ваш-коннектор" aria-label="Permalink to &quot;Что должен делать ваш коннектор&quot;">​</a></h2><ol><li><strong>Получить</strong> реестр по HTTPS: <code>GET</code> на настроенный эндпоинт, распарсить JSON-объект верхнего уровня — <code>payload</code> и <code>signature</code>. Захватить сырую JSON-подстроку <code>payload</code> ровно в том виде, в котором она получена, <strong>до</strong> какой-либо десериализации. Именно эта побайтовая строка покрывается подписью; её переcериализация (другой порядок ключей, другие пробелы) сделает проверку невалидной.</li><li><strong>Канонизировать</strong> эту сырую строку по спецификации <a href="https://datatracker.ietf.org/doc/html/rfc8785" target="_blank" rel="noreferrer">JCS, RFC 8785</a>: отсортировать ключи объекта по Unicode code point, убрать незначащие пробелы, применить стандартные правила сериализации чисел и строк.</li><li><strong>Хэшировать</strong> канонизированные байты алгоритмом SHA-512.</li><li><strong>Проверить</strong> поле <code>signature</code> (после Base64-декодирования) против этого хэша алгоритмом RSA PKCS#1 v1.5, используя публичный ключ, встроенный в ваше приложение (<code>pub.pem</code>, сгенерированный вместе с ключом подписи на сервере — см. <a href="./architecture#генерация-ключеи-подписи">Генерация ключей подписи</a>). Принимайте публичный ключ в удобном для вашей стратегии встраивания формате: PEM, Base64-кодированный PEM, или сырой DER (SPKI) — оба официальных SDK поддерживают все три формата именно по этой причине.</li><li><strong>Fail closed.</strong> Если подпись не проверяется, эндпоинт недоступен, или ответ некорректно сформирован — не создавайте запиненный клиент и не откатывайтесь молча на незапиненный. Прервите инициализацию или перейдите в деградированный, видимый пользователю режим. Ни один официальный SDK никогда не создаёт частично проверенный или &quot;best-effort&quot; запиненный клиент — здесь нет безопасной середины.</li><li><strong>Применить пины.</strong> После успешной проверки десериализуйте <code>payload.keys</code> и настройте пиннинг сертификата/публичного ключа вашего HTTP-клиента SHA-256 SPKI-хэшем из поля <code>key</code> каждой записи, привязанным к её <code>domainName</code>. Точное значение полей — в разделе <a href="./architecture#формат-подписанного-реестра">Формат подписанного реестра</a>.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ваше приложение</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ GET &lt;endpoint&gt;                         → { payload, signature }</span></span>
<span class="line"><span>   ├─ canonicalize(raw payload string)  [JCS]</span></span>
<span class="line"><span>   ├─ sha512(canonical)</span></span>
<span class="line"><span>   ├─ verify(signature, hash, embedded pubkey)  [RSA PKCS#1 v1.5]</span></span>
<span class="line"><span>   │    ├─ fail  → прервать / деградированный режим, без запиненного клиента</span></span>
<span class="line"><span>   │    └─ pass  → разобрать payload.keys</span></span>
<span class="line"><span>   │                для каждого ключа: запинить sha256(SPKI) к domainName</span></span>
<span class="line"><span>   │                в механизме пиннинга вашего TLS/HTTP-стека</span></span>
<span class="line"><span>   └─ готово</span></span></code></pre></div><h2 id="почему-это-безопасно-делать-самостоятельно" tabindex="-1">Почему это безопасно делать самостоятельно <a class="header-anchor" href="#почему-это-безопасно-делать-самостоятельно" aria-label="Permalink to &quot;Почему это безопасно делать самостоятельно&quot;">​</a></h2><p>Подпись реестра — единственное, что стоит между подделанным и доверенным ответом, и это стандартная RSA-подпись над стандартной схемой канонизации, а не проприетарный протокол. Любая платформа с примитивом проверки RSA-подписи и корректной реализацией JCS может валидировать её правильно. Два официальных SDK существуют ради удобства (настройка HTTP-клиента, интеграция с API пиннинга) — а не потому, что сам протокол требует специфичного для платформы доверия.</p><h2 id="где-взять-остальные-детали" tabindex="-1">Где взять остальные детали <a class="header-anchor" href="#где-взять-остальные-детали" aria-label="Permalink to &quot;Где взять остальные детали&quot;">​</a></h2><ul><li>Эндпоинт реестра и форма ответа: <a href="./self-hosting">Self-hosting</a> и <a href="./../reference/http-api">HTTP API</a>.</li><li>Точная JSON-схема, которую вы канонизируете и проверяете: <a href="./architecture#формат-подписанного-реестра">Формат подписанного реестра</a>.</li><li>Проработанная, специфичная для языка референс-реализация каждого шага выше: исходники <a href="./android-sdk">Android SDK</a> (Kotlin) и <a href="./ios-macos-sdk">Apple SDK</a> (Swift) открыты — прочитать любой из них быстрее, чем заново выводить RFC 8785 с нуля, если нужны побайтовые детали.</li></ul>`,9)])])}const S=e(t,[["render",r]]);export{u as __pageData,S as default};
